 * Validates the whole batch — no address twice, none already a member or
 * already holding a pending invitation, the seats fit — and only then writes
 * anything, so a refused batch leaves no invitation behind. `replacing` is the
 * invitation a re-send is about to withdraw: it neither blocks its own address
 * nor holds a seat against its replacement.
 */
async function issueInvitations(
  actor: Actor,
  org: Organization,
  invites: readonly { email: string; role: Role }[],
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  const orgId = org.id;

  const batchEmails = new Set<string>();
  for (const invite of invites) {
    const key = emailKey(invite.email);
    if (batchEmails.has(key)) {
      throw new Error(`${invite.email} is named more than once in this batch`);
    }
    batchEmails.add(key);
  }

  const memberEmails = await memberRepo.listCurrentMemberEmails(orgId, [
    ...batchEmails,
  ]);
  for (const invite of invites) {
    if (memberEmails.has(emailKey(invite.email))) {
      throw new Error(`${invite.email} is already a member of this workspace`);
    }
  }

  const pending = (await invitationRepo.listPendingInvitations(orgId)).filter(
    (row) => row.id !== replacing?.id,
  );
  const pendingEmails = new Set(pending.map((row) => emailKey(row.email)));
  for (const invite of invites) {
    if (pendingEmails.has(emailKey(invite.email))) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) + pending.length;

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: invite.email,
        role: invite.role,
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/** Addresses are compared without regard to letter case. */
function emailKey(email: string): string {
  return email.toLowerCase();
}

async function chargeInviteRateLimit(
  orgId: OrgId,
  invites: number,
): Promise<void> {
  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, invites);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }
}

/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 * The token alone is not enough, though — a forwarded link must not work for
 * anyone but the address the invitation was sent to.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error(
      "That invitation is no longer valid: its workspace has been deleted",
    );
  }

  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (emailKey(user.email) !== emailKey(invitation.email)) {
    throw new Error("That invitation was sent to a different email address");
  }

  const at = toIsoTimestamp(new Date());

  const current = await memberRepo.findMember(invitation.orgId, userId);
  if (current) {
    // Already inside: nothing to grant, but the invitation is still used up.
    await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, at);
    return current;
  }

  // A former member gets their old row back — `members_org_user_idx` allows
  // one row per (org, user) — under the role and inviter of this invitation.
  const former = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );
  const member = former
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        former.id,
        invitation.role,
        invitation.invitedBy,
        at,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
        at,
      );

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, at);

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

