import { eq } from "drizzle-orm";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

async function seedInvite(tenant: Awaited<ReturnType<typeof createTenant>>, email: string, token: string, role: "admin"|"member"|"viewer" = "member", days = 14) {
  return invitationRepo.insertInvitation(tenant.org.id, { orgId: tenant.org.id, email, role, expiresInDays: days }, tenant.userIds.admin, hashToken(token));
}

describe("scenarios", () => {
  it("1/2/3: new member becomes active; expiry is 14 days", async () => {
    const t = await createTenant("s1", "growth");
    const inv = await seedInvite(t, "new@s1.test", "a".repeat(32));
    const days = (Date.parse(inv.expiresAt) - Date.parse(inv.createdAt)) / 86_400_000;
    expect(days).toBeCloseTo(14, 3);
    const u = await userRepo.insertUser({ email: "new@s1.test", name: "n", passwordHash: "x" });
    const m = await invitationService.acceptInvitation(u.id, { token: "a".repeat(32) });
    expect(m.status).toBe("active");
    expect(await resolveActor(u.id, t.org.id)).not.toBeNull();
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(5);
    await expect(invitationService.acceptInvitation(u.id, { token: "a".repeat(32) })).rejects.toThrow(/already/);
  });

  it("rejoin + counters + notifications + sessions", async () => {
    const off = registerUsageListeners();
    const t = await createTenant("s2", "growth");
    await usageRepo.recomputeUsage(t.org.id);
    const before = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    expect(before).toBe(4);

    const viewerMember = (await memberRepo.findMember(t.org.id, t.userIds.viewer))!;
    // session defaulting to the org, plus another session elsewhere
    const db = getDb();
    const now = new Date().toISOString();
    const other = "01HZZZOTHERORGAAAAAAAAAAAA";
    db.insert(sessions).values([
      { id: "sess1", userId: t.userIds.viewer, activeOrgId: t.org.id, tokenHash: "h1", expiresAt: "2999-01-01T00:00:00.000Z", createdAt: now, updatedAt: now },
      { id: "sess2", userId: t.userIds.viewer, activeOrgId: other, tokenHash: "h2", expiresAt: "2999-01-01T00:00:00.000Z", createdAt: now, updatedAt: now },
      { id: "sess3", userId: t.userIds.member, activeOrgId: t.org.id, tokenHash: "h3", expiresAt: "2999-01-01T00:00:00.000Z", createdAt: now, updatedAt: now },
    ]).run();

    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.viewer, kind: "comment_created", inApp: true, email: false, digestOnly: true });
    expect(await digestService.listDigestRecipients(t.org.id)).toContain(t.userIds.viewer);

    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewerMember.id });
    await expect(memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewerMember.id })).rejects.toThrow();
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(3);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(3);

    const s = (id: string) => db.select().from(sessions).where(eq(sessions.id, id)).get()!.activeOrgId;
    expect(s("sess1")).toBeNull();
    expect(s("sess2")).toBe(other);
    expect(s("sess3")).toBe(t.org.id);

    expect(await digestService.listDigestRecipients(t.org.id)).not.toContain(t.userIds.viewer);
    const rows = await notify(t.org.id, "issue_assigned", [t.userIds.viewer, t.userIds.admin], { title: "x", body: "y", href: "/", actorId: null });
    expect(rows.map((r) => r.recipientId)).toEqual([t.userIds.admin]);

    // invite again (case-different address), accepted by the same account
    const joined: unknown[] = [];
    const offJoin = subscribe("member.joined", (p) => { joined.push(p); });
    const inv = await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: `Viewer@s2.TEST`, role: "admin" });
    expect(inv.role).toBe("admin");
    // raw token unknown: re-seed a known token instead
    await invitationRepo.revokeInvitation(t.org.id, inv.id);
    await seedInvite(t, "viewer@s2.test", "b".repeat(32), "admin");
    const back = await invitationService.acceptInvitation(t.userIds.viewer, { token: "b".repeat(32) });
    offJoin();
    expect(back.id).toBe(viewerMember.id);
    expect(back.role).toBe("admin");
    expect(back.invitedBy).toBe(t.userIds.admin);
    expect(back.status).toBe("active");
    expect(back.archivedAt).toBeNull();
    expect(joined).toHaveLength(1);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(4);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    const rows2 = await notify(t.org.id, "issue_assigned", [t.userIds.viewer], { title: "x", body: "y", href: "/", actorId: null });
    expect(rows2).toHaveLength(1);
    expect(await digestService.listDigestRecipients(t.org.id)).toContain(t.userIds.viewer);
    const owner = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.owner, unreadOnly: false, kind: ["member_joined"], limit: 25, cursor: null });
    expect(owner.items.length).toBeGreaterThan(0);
    off();
  });

  it("4/5: pending semantic, duplicates", async () => {
    const t = await createTenant("s4", "starter");
    // expired + revoked don't hold seats
    await seedInvite(t, "old@s4.test", "c".repeat(32), "member", -3);
